      <CtaButtons
        primaryCta={content.primaryCta}
        secondaryCta={content.secondaryCta}
      />

      <PipelineDemo />

      <BrandsSectionV6 />
    </div>
  )
}

"use client"

import { useLayoutEffect, useRef } from "react"
import Link from "next/link"
import gsap from "gsap"

import { cn } from "@/lib/utils"

import type { HeroV7Cta } from "../lib/config"
import { heroV7Content } from "../lib/config"

const CHAR_STAGGER = 0.03
const DURATION = 0.45
const EASE = "power3.out"

function playIn(row1: HTMLElement[], row2: HTMLElement[]) {
  gsap.killTweensOf([...row1, ...row2])
  gsap.to(row1, {
    yPercent: -100,
    duration: DURATION,
    stagger: CHAR_STAGGER,
    ease: EASE,
    overwrite: "auto",
  })
  gsap.to(row2, {
    yPercent: 0,
    duration: DURATION,
    stagger: CHAR_STAGGER,
    ease: EASE,
    overwrite: "auto",
  })
}

function playOut(row1: HTMLElement[], row2: HTMLElement[]) {
  gsap.killTweensOf([...row1, ...row2])
  gsap.to(row1, {
    yPercent: 0,
    duration: DURATION,
    stagger: { each: CHAR_STAGGER, from: "end" },
    ease: EASE,
    overwrite: "auto",
  })
  gsap.to(row2, {
    yPercent: 100,
    duration: DURATION,
    stagger: { each: CHAR_STAGGER, from: "end" },
    ease: EASE,
    overwrite: "auto",
  })
}

function useStaggerCtaAnimation(label: string) {
  const linkRef = useRef<HTMLAnchorElement>(null)

  useLayoutEffect(() => {
    const link = linkRef.current
    if (!link) return

    const row1 = gsap.utils.toArray<HTMLElement>(
      ".hero-v7-cta__stagger-text:not(.hero-v7-cta__stagger-text--second) .hero-v7-cta__char",
      link,
    )
    const row2 = gsap.utils.toArray<HTMLElement>(
      ".hero-v7-cta__stagger-text--second .hero-v7-cta__char",
      link,
    )

    if (row1.length === 0 || row2.length === 0) return

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    if (reduced) {
      gsap.set([...row1, ...row2], { clearProps: "all" })
      return
    }

    gsap.set(row1, { yPercent: 0 })
    gsap.set(row2, { yPercent: 100 })

    let over = false
    let pressed = false

    const sync = () => {
      if (over || pressed) playIn(row1, row2)
      else playOut(row1, row2)
    }

    const onEnter = () => {
      over = true
      sync()
    }

    const onLeave = () => {
      over = false
      pressed = false
      sync()
    }

    const onDown = (event: PointerEvent) => {
      if (!event.isPrimary) return
      if (event.pointerType === "mouse" && event.button !== 0) return
      pressed = true
      if (event.pointerType === "touch" || event.pointerType === "pen") {
        try {
          link.setPointerCapture(event.pointerId)
        } catch {
          /* ignore */
        }
      }
      sync()
    }

    const onUp = (event: PointerEvent) => {
      pressed = false
      try {
        if (link.hasPointerCapture(event.pointerId)) {
          link.releasePointerCapture(event.pointerId)
        }
      } catch {
        /* ignore */
      }
      if (event.pointerType === "touch") over = false
      sync()
    }

    const onCancel = (event: PointerEvent) => {
      pressed = false
      try {
        if (link.hasPointerCapture(event.pointerId)) {
          link.releasePointerCapture(event.pointerId)
        }
      } catch {
        /* ignore */
      }
      sync()
    }

    link.addEventListener("pointerenter", onEnter)
    link.addEventListener("pointerleave", onLeave)
    link.addEventListener("pointerdown", onDown)
    link.addEventListener("pointerup", onUp)
    link.addEventListener("pointercancel", onCancel)

    return () => {
      link.removeEventListener("pointerenter", onEnter)
      link.removeEventListener("pointerleave", onLeave)
      link.removeEventListener("pointerdown", onDown)
      link.removeEventListener("pointerup", onUp)
      link.removeEventListener("pointercancel", onCancel)
      gsap.killTweensOf([...row1, ...row2])
    }
  }, [label])

  return linkRef
}

function StaggerChars({ chars }: { chars: string[] }) {
  return (
    <>
      {chars.map((char, i) => (
        <span key={`${char}-${i}`} className="hero-v7-cta__char">
          {char === " " ? "\u00a0" : char}
        </span>
      ))}
    </>
  )
}

function FlipCtaButton({
  href,
  label,
  variant = "primary",
  className,
}: {
  href: string
  label: string
  variant?: "primary" | "secondary"
  className?: string
}) {
  const linkRef = useStaggerCtaAnimation(label)

  return (
    <Link
      ref={linkRef}
      href={href}
      className={cn(
        "hero-v7-cta",
        variant === "primary" && "hero-v7-cta--primary",
        variant === "secondary" && "hero-v7-cta--secondary",
        className,
      )}
      style={{ touchAction: "manipulation" }}
    >
      <span className="hero-v7-cta__glow" aria-hidden="true" />
      <span className="hero-v7-cta__stagger-wrapper">
        <span className="hero-v7-cta__stagger-text">
          <StaggerChars chars={label.split("")} />
        </span>
        <span
          className="hero-v7-cta__stagger-text hero-v7-cta__stagger-text--second"
          aria-hidden="true"
        >
          <StaggerChars chars={label.split("")} />
        </span>
      </span>
    </Link>
  )
}

export default function CtaButtons({
  primaryCta = heroV7Content.primaryCta,
  secondaryCta = heroV7Content.secondaryCta,
}: {
  primaryCta?: HeroV7Cta
  secondaryCta?: HeroV7Cta
}) {
  return (
    <div className="flex flex-row flex-wrap justify-center gap-3">
      <FlipCtaButton
        href={primaryCta.href}
        label={primaryCta.label}
        variant="primary"
        className="w-full sm:w-auto"
      />
      <FlipCtaButton
        href={secondaryCta.href}
        label={secondaryCta.label}
        variant="secondary"
        className="w-full sm:w-auto"
      />
    </div>
  )
}

"use client"

import {
  ArrowsLeftRight,
  Circle,
  Database,
  PlugsConnected,
} from "@phosphor-icons/react"

import { cn } from "@/lib/utils"
import { Salesforce } from "@/components/ui/svgs/salesforce"
import { Slack } from "@/components/ui/svgs/slack"
import { Stripe } from "@/components/ui/svgs/stripe"

import { usePipelineDemoAnimation } from "../hooks/use-pipeline-demo-animation"
import {
  DESTINATION_CHIPS,
  PIPELINE_STAGES,
} from "../lib/pipeline-config"

import "../styles/hero-section-v7.css"

const DESTINATION_LOGOS = {
  slack: Slack,
  salesforce: Salesforce,
  stripe: Stripe,
} as const

const STAGE_ICONS = {
  ingest: PlugsConnected,
  transform: ArrowsLeftRight,
  deliver: Database,
} as const

type StageId = keyof typeof STAGE_ICONS

function StageNode({
  stageId,
  label,
  detail,
  active,
}: {
  stageId: StageId
  label: string
  detail: string
  active: boolean
}) {
  const Icon = STAGE_ICONS[stageId]

  return (
    <div
      className={cn(
        "hero-v7-pipeline__node",
        `hero-v7-pipeline__node--${stageId}`,
        active && "hero-v7-pipeline__node--active",
      )}
    >
      <span className="hero-v7-pipeline__node-icon" aria-hidden>
        <Icon size={18} weight="duotone" />
      </span>
      <span className="hero-v7-pipeline__node-label">{label}</span>
      <span className="hero-v7-pipeline__node-detail">{detail}</span>
    </div>
  )
}

export default function PipelineDemo() {
  const { run, stage, activeDestinations, lineARef, lineBRef } =
    usePipelineDemoAnimation()

  const isStageActive = (id: StageId) => stage === id

  return (
    <div
      className="hero-v7-pipeline mx-auto w-full max-w-3xl text-left"
      aria-label="Live integration pipeline demo"
    >
      <div className="hero-v7-pipeline__shell">
        <header className="hero-v7-pipeline__header">
          <div className="hero-v7-pipeline__header-main">
            <span className="hero-v7-pipeline__run-id font-mono">{run.id}</span>
            <span className="hero-v7-pipeline__status">
              <Circle
                className={cn(
                  "hero-v7-pipeline__status-dot",
                  stage !== "idle" && "hero-v7-pipeline__status-dot--live",
                )}
                size={8}
                weight="fill"
                aria-hidden
              />
              <span className="font-mono text-[11px] uppercase tracking-wider">
                {stage === "idle" ? "Routed" : "Live"}
              </span>
            </span>
          </div>
          <span className="hero-v7-pipeline__latency font-mono tabular-nums">
            {run.latencyMs}
            <span className="text-muted-foreground">ms</span>
          </span>
        </header>

        <div className="hero-v7-pipeline__track">
          <div className="hero-v7-pipeline__nodes">
            <StageNode
              stageId="ingest"
              label={PIPELINE_STAGES[0].label}
              detail={PIPELINE_STAGES[0].detail}
              active={isStageActive("ingest")}
            />

            <div
              ref={lineARef}
              className="hero-v7-pipeline__line hero-v7-pipeline__line--a"
              aria-hidden
            />

            <StageNode
              stageId="transform"
              label={PIPELINE_STAGES[1].label}
              detail={PIPELINE_STAGES[1].detail}
              active={isStageActive("transform")}
            />

            <div
              ref={lineBRef}
              className="hero-v7-pipeline__line hero-v7-pipeline__line--b"
              aria-hidden
            />

            <StageNode
              stageId="deliver"
              label={PIPELINE_STAGES[2].label}
              detail={PIPELINE_STAGES[2].detail}
              active={isStageActive("deliver")}
            />
          </div>

          <div
            className="hero-v7-pipeline__badges"
            aria-label="Delivery destinations"
          >
            {DESTINATION_CHIPS.map((chip) => {
              const lit =
                activeDestinations.includes(chip.label) ||
                (stage === "idle" && run.destinations.includes(chip.label))
              const Logo = DESTINATION_LOGOS[chip.id]
              return (
                <span
                  key={chip.id}
                  className={cn(
                    "hero-v7-pipeline__chip",
                    `hero-v7-pipeline__chip--${chip.id}`,
                    lit && "hero-v7-pipeline__chip--lit",
                  )}
                >
                  <Logo className="hero-v7-pipeline__chip-logo" />
                  <span className="sr-only">{chip.label}</span>
                </span>
              )
            })}
          </div>
        </div>

        <footer className="hero-v7-pipeline__log font-mono">
          <span className="hero-v7-pipeline__log-step hero-v7-pipeline__log-step--source">
            {run.source}
          </span>
          <span className="hero-v7-pipeline__log-arrow" aria-hidden>
            →
          </span>
          <span className="hero-v7-pipeline__log-step hero-v7-pipeline__log-step--transform">
            {run.transform}
          </span>
          <span className="hero-v7-pipeline__log-arrow" aria-hidden>
            →
          </span>
          <span className="hero-v7-pipeline__log-step hero-v7-pipeline__log-step--dest">
            {run.destinations.join(" + ")}
          </span>
        </footer>
      </div>
    </div>
  )
}

import type { Brand } from "../lib/brands"
import BrandLogo from "./brand-logo"

export default function Marquee({ brands }: { brands: Brand[] }) {
  return (
    <div className="bs6-marquee-wrap w-full min-w-0">
      <div className="bs6-fade bs6-fade-left" aria-hidden />
      <div className="bs6-fade bs6-fade-right" aria-hidden />

      <div className="bs6-track">
        <div className="bs6-set" role="list" aria-label="Brand logos">
          {brands.map((brand) => (
            <div key={brand.name} role="listitem" className="bs6-slot flex shrink-0 items-center justify-center">
              <BrandLogo brand={brand} />
            </div>
          ))}
        </div>
        <div className="bs6-set" aria-hidden>
          {brands.map((brand) => (
            <div key={`dup-${brand.name}`} className="bs6-slot flex shrink-0 items-center justify-center">
              <BrandLogo brand={brand} />
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

import type { Brand } from "../lib/brands"

export default function BrandLogo({ brand }: { brand: Brand }) {
  const Light = brand.light
  const Dark = brand.dark

  if (Dark) {
    return (
      <span className="inline-flex h-7 w-32 items-center justify-center md:h-8 md:w-36">
        <Light className="bs6-logo-img block h-full w-full dark:hidden" aria-label={brand.name} />
        <Dark className="bs6-logo-img hidden h-full w-full dark:block" aria-label={brand.name} />
      </span>
    )
  }

  return (
    <span className="inline-flex h-7 w-32 items-center justify-center md:h-8 md:w-36">
      <Light className="bs6-logo-img h-full w-full" aria-label={brand.name} />
    </span>
  )
}

"use client"

import { useLayoutEffect, useRef, useState } from "react"
import gsap from "gsap"

import { PIPELINE_RUNS } from "../lib/pipeline-config"

type Stage = "ingest" | "transform" | "deliver" | "idle"

const STAGE_HOLD_S = 0.55
const LINE_FILL_S = 0.65

export function usePipelineDemoAnimation() {
  const lineARef = useRef<HTMLDivElement>(null)
  const lineBRef = useRef<HTMLDivElement>(null)
  const runIndexRef = useRef(0)

  const [runIndex, setRunIndex] = useState(0)
  const [stage, setStage] = useState<Stage>("idle")
  const [activeDestinations, setActiveDestinations] = useState<string[]>([])

  const run = PIPELINE_RUNS[runIndex]

  useLayoutEffect(() => {
    const lineA = lineARef.current
    const lineB = lineBRef.current

    if (!lineA || !lineB) {
      return
    }

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    const initialRun = PIPELINE_RUNS[runIndexRef.current]

    if (reduced) {
      setStage("deliver")
      setActiveDestinations(initialRun.destinations)
      gsap.set([lineA, lineB], { "--hero-v7-pipeline-line-progress": "100%" })
      return
    }

    let cancelled = false

    const resetLines = () => {
      gsap.set([lineA, lineB], { "--hero-v7-pipeline-line-progress": "0%" })
    }

    const fillLine = (line: HTMLDivElement, duration: number) =>
      gsap.to(line, {
        "--hero-v7-pipeline-line-progress": "100%",
        duration,
        ease: "power2.out",
      })

    const runCycle = (index: number) => {
      if (cancelled) return

      runIndexRef.current = index
      const current = PIPELINE_RUNS[index]
      setRunIndex(index)
      setStage("ingest")
      setActiveDestinations([])
      resetLines()

      const tl = gsap.timeline({
        onComplete: () => {
          if (cancelled) return
          const next = (index + 1) % PIPELINE_RUNS.length
          gsap.delayedCall(0.85, () => runCycle(next))
        },
      })

      tl.call(() => setStage("ingest"))
        .to({}, { duration: STAGE_HOLD_S })
        .call(() => {
          setStage("transform")
          fillLine(lineA, LINE_FILL_S)
        })
        .to({}, { duration: LINE_FILL_S })
        .call(() => {
          setStage("deliver")
          fillLine(lineB, LINE_FILL_S)
          setActiveDestinations(current.destinations)
        })
        .to({}, { duration: LINE_FILL_S })
        .call(() => setStage("idle"))
    }

    const startDelay = gsap.delayedCall(0.4, () => runCycle(runIndexRef.current))

    const onResize = () => {
      gsap.killTweensOf([lineA, lineB])
      startDelay.kill()
      gsap.delayedCall(0.15, () => runCycle(runIndexRef.current))
    }

    window.addEventListener("resize", onResize)

    return () => {
      cancelled = true
      startDelay.kill()
      gsap.killTweensOf([lineA, lineB])
      window.removeEventListener("resize", onResize)
    }
  }, [])

  return {
    run,
    stage,
    activeDestinations,
    lineARef,
    lineBRef,
  }
}

export type HeroV7Cta = {
  label: string
  href: string
}

export type HeroV7Content = {
  title: string
  description: string
  primaryCta: HeroV7Cta
  secondaryCta: HeroV7Cta
}

/** Edit these defaults after installing the block, or pass overrides to `<HeroSectionV7 />`. */
export const heroV7Content: HeroV7Content = {
  title: "Ship integrations without rewiring your stack",
  description:
    "One layer to ingest, transform, and deliver events to the tools you already run.",
  primaryCta: { label: "Get started", href: "/signup" },
  secondaryCta: { label: "View docs", href: "/docs" },
}

export type HeroV7Props = Partial<HeroV7Content>

export function resolveHeroV7Content(overrides?: HeroV7Props): HeroV7Content {
  return {
    title: overrides?.title ?? heroV7Content.title,
    description: overrides?.description ?? heroV7Content.description,
    primaryCta: overrides?.primaryCta ?? heroV7Content.primaryCta,
    secondaryCta: overrides?.secondaryCta ?? heroV7Content.secondaryCta,
  }
}

export type PipelineRun = {
  id: string
  source: string
  transform: string
  destinations: string[]
  latencyMs: number
}

/** Example runs — replace with your product’s events and destinations. */
export const PIPELINE_RUNS: PipelineRun[] = [
  {
    id: "evt_8f2a91",
    source: "user.created",
    transform: "enrich.profile",
    destinations: ["Slack", "Salesforce"],
    latencyMs: 47,
  },
  {
    id: "evt_3c17bd",
    source: "invoice.paid",
    transform: "map.revenue",
    destinations: ["Salesforce", "Stripe"],
    latencyMs: 62,
  },
  {
    id: "evt_d904e2",
    source: "ticket.opened",
    transform: "route.owner",
    destinations: ["Slack", "Stripe"],
    latencyMs: 38,
  },
  {
    id: "evt_51aa0f",
    source: "account.updated",
    transform: "sync.crm",
    destinations: ["Slack", "Salesforce"],
    latencyMs: 54,
  },
]

export const PIPELINE_STAGES = [
  {
    id: "ingest",
    label: "Ingest",
    detail: "Webhooks & streams",
  },
  {
    id: "transform",
    label: "Transform",
    detail: "Map · filter · enrich",
  },
  {
    id: "deliver",
    label: "Deliver",
    detail: "Apps & APIs",
  },
] as const

/** Destination badges — swap labels and ids for your integrations. */
export const DESTINATION_CHIPS = [
  { id: "slack", label: "Slack" },
  { id: "salesforce", label: "Salesforce" },
  { id: "stripe", label: "Stripe" },
] as const

export type DestinationId = (typeof DESTINATION_CHIPS)[number]["id"]

.hero-v7 {
  --hero-v7-ease-out: cubic-bezier(0.22, 1, 0.36, 1);
}

.hero-v7-cta {
  position: relative;
  display: inline-flex;
  min-height: 2.5rem;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: #141414;
  color: #f4f4f5;
  padding: 0.5rem 1.375rem;
  font-family: var(--font-mono, ui-monospace, monospace);
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  line-height: 1;
  text-transform: uppercase;
  text-decoration: none;
  outline: none;
  transition:
    background-color 0.25s ease,
    border-color 0.25s ease,
    color 0.25s ease;
}

.hero-v7-cta--primary {
  --hero-v7-cta-glow: rgba(59, 130, 246, 0.65);
  --hero-v7-cta-glow-soft: rgba(59, 130, 246, 0.28);
}

.hero-v7-cta--secondary {
  --hero-v7-cta-glow: rgba(249, 115, 22, 0.65);
  --hero-v7-cta-glow-soft: rgba(249, 115, 22, 0.28);
  border-color: rgba(24, 24, 27, 0.14);
  background: #f4f4f5;
  color: #18181b;
}

.hero-v7-cta__glow {
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s var(--hero-v7-ease-out);
  box-shadow:
    0 0 0 1px var(--hero-v7-cta-glow),
    0 0 16px var(--hero-v7-cta-glow-soft),
    0 0 32px color-mix(in srgb, var(--hero-v7-cta-glow-soft) 65%, transparent);
}

.hero-v7-cta:hover .hero-v7-cta__glow,
.hero-v7-cta:focus-visible .hero-v7-cta__glow,
.hero-v7-cta:active .hero-v7-cta__glow {
  opacity: 1;
}

.hero-v7-cta:focus-visible {
  box-shadow: 0 0 0 2px
    color-mix(in srgb, var(--hero-v7-cta-glow) 55%, transparent);
}

.hero-v7-cta__stagger-wrapper {
  position: relative;
  display: inline-block;
  overflow: hidden;
  line-height: 1;
}

.hero-v7-cta__stagger-text {
  display: inline-flex;
  flex-wrap: wrap;
  justify-content: center;
  row-gap: 0;
}

.hero-v7-cta__stagger-text--second {
  position: absolute;
  inset: 0;
  justify-content: center;
}

.hero-v7-cta__char {
  display: inline-block;
  will-change: transform;
}

.hero-v7-cta--primary:hover,
.hero-v7-cta--primary:focus-visible,
