  margin-top: 0.5rem;
}

.hero-v7-pipeline__shell {
  overflow: hidden;
  border-radius: 1rem;
  border: 1px solid rgba(24, 24, 27, 0.1);
  background: #fafafa;
  box-shadow: 0 24px 48px -28px rgba(24, 24, 27, 0.18);
}

.dark .hero-v7-pipeline__shell {
  border-color: rgba(255, 255, 255, 0.1);
  background: #141414;
  box-shadow: 0 24px 48px -28px rgba(0, 0, 0, 0.45);
