  min-width: 0;
  align-items: center;
  gap: 0.75rem;
}

.hero-v7-pipeline__run-id {
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  color: #71717a;
}

.dark .hero-v7-pipeline__run-id {
  color: #a1a1aa;
}

.hero-v7-pipeline__status {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  color: #52525b;
}

.dark .hero-v7-pipeline__status {
  color: #d4d4d8;
}

.hero-v7-pipeline__status-dot {
  color: #a1a1aa;
  transition: color 0.25s ease;
}

.hero-v7-pipeline__status-dot--live {
  color: #22c55e;
}

.hero-v7-pipeline__latency {
  font-size: 0.8125rem;
  color: #18181b;
}

.dark .hero-v7-pipeline__latency {
  color: #f4f4f5;
}

.hero-v7-pipeline__track {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1.25rem 1rem 1rem;
}

.hero-v7-pipeline__nodes {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
  gap: 0.75rem;
}

@media (min-width: 640px) {
