.hero-v7-pipeline__line {
  --hero-v7-pipeline-line-progress: 0%;
  position: relative;
  display: none;
  height: 2px;
  align-self: center;
  border-radius: 9999px;
  background: rgba(24, 24, 27, 0.08);
  overflow: hidden;
}

.dark .hero-v7-pipeline__line {
  background: rgba(255, 255, 255, 0.08);
}

@media (min-width: 640px) {
  .hero-v7-pipeline__line {
    display: block;
  }
}

.hero-v7-pipeline__line::after {
  content: "";
  position: absolute;
  inset: 0;
  width: var(--hero-v7-pipeline-line-progress, 0%);
  border-radius: inherit;
  background: #52525b;
  transition: width 0.05s linear;
}

.dark .hero-v7-pipeline__line::after {
  background: #a1a1aa;
}

.hero-v7-pipeline__node {
  display: flex;
  min-height: 5.5rem;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  border-radius: 0.75rem;
  border: 1px solid rgba(24, 24, 27, 0.12);
  padding: 0.625rem 0.5rem;
  text-align: center;
  transition:
    border-color 0.3s var(--hero-v7-ease-out),
    color 0.3s var(--hero-v7-ease-out);
}

.dark .hero-v7-pipeline__node {
  border-color: rgba(255, 255, 255, 0.12);
}

.hero-v7-pipeline__node-icon {
  display: inline-flex;
  color: #a1a1aa;
  transition: color 0.3s var(--hero-v7-ease-out);
}

.hero-v7-pipeline__node-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
